      "do_helix": { key: "do_helix", label: "Mask a 3D helix?", type: "bool", default: false, help: `Generate a mask for 3D helix which spans across Z axis of the box.` },
      "extend_inimask": { key: "extend_inimask", label: "Extend binary map this many pixels:", type: "number", default: 3, min: 0, max: 20, step: 1, flag: "--extend_inimask", help: `The initial binary mask is extended this number of pixels in all directions.` },
      "fn_in": { key: "fn_in", label: "Input 3D map:", type: "text", default: "LABEL_MAP_CPIPE", flag: "--i", help: `` },
      "helical_z_percentage": { key: "helical_z_percentage", label: "Central Z length (%):", type: "number", default: 30, min: 5, max: 80, step: 1, help: `Reconstructed helix suffers from inaccuracies of orientation searches. The central part of the box contains more reliable information compared to the top and bottom parts along Z axis. Set this value (%) to the central part length along Z axis divided by the box size. Values around 30% are commonly used but you may want to try different lengths.` },
      "inimask_threshold": { key: "inimask_threshold", label: "Initial binarisation threshold:", type: "number", default: 0.02, min: 0, max: 0.5, step: 0.01, flag: "--ini_threshold", help: `This threshold is used to make an initial binary mask from the average of the two unfiltered half-reconstructions. If you don't know what value to use, display one of the unfiltered half-maps in a 3D surface rendering viewer and find the lowest threshold that gives no noise peaks outside the reconstruction.` },
      "lowpass_filter": { key: "lowpass_filter", label: "Lowpass filter map (A)", type: "number", default: 15, min: 10, max: 100, step: 5, flag: "--lowpass", help: `Lowpass filter that will be applied to the input map, prior to binarization. To calculate solvent masks, a lowpass filter of 15-20A may work well.` },
      "width_mask_edge": { key: "width_mask_edge", label: "Add a soft-edge of this many pixels:", type: "number", default: 3, min: 0, max: 20, step: 1, flag: "--width_soft_edge", help: `The extended binary mask is further extended with a raised-cosine soft edge of the specified width.` },
