      "F1": { key: "F1", label: "HMMSearch F1: ", type: "number", default: 0.02, min: 1, max: 10, step: 0.1, help: `F1 parameter for HMMSearch, see their documentation at http://eddylab.org/software/hmmer/Userguide.pdf` },
      "F2": { key: "F2", label: "HMMSearch F2: ", type: "number", default: 0.001, min: 1, max: 10, step: 0.1, help: `F2 parameter for HMMSearch, see their documentation at http://eddylab.org/software/hmmer/Userguide.pdf` },
      "F3": { key: "F3", label: "HMMSearch F3: ", type: "number", default: 0.00001, min: 0, max: 10, step: 0.1, help: `F3 parameter for HMMSearch, see their documentation at http://eddylab.org/software/hmmer/Userguide.pdf` },
      "alphabet": { key: "alphabet", label: "Alphabet for the HMMer search:", type: "select", default: "amino", radio: ["amino","DNA","RNA"], help: `` },
