      "do_hhmer": { key: "do_hhmer", label: "Perform HMMer search?", type: "bool", default: false, help: `If set to Yes, model-angelo will perform a HMM search using HHMer in the output directory of the model-angelo run (without sequence). You can continue an old run with this option switched on, and the model building step will be skipped if the output .cif exists. This way, you can try multiple HHMer runs.` },
      "fn_lib": { key: "fn_lib", label: "Library with sequences for HMMer search:", type: "text", default: "LABEL_SEQUENCE_CPIPE", help: `` },
      "fn_map": { key: "fn_map", label: "B-factor sharpened map:", type: "text", default: "LABEL_MAP_CPIPE", help: `` },
      "fn_modelangelo_exe": { key: "fn_modelangelo_exe", label: "ModelAngelo executable:", type: "text", default: "std::string(\"relion_python_modelangelo\")", help: `` },
      "gpu_id": { key: "gpu_id", label: "Which GPUs to use:", type: "text", default: "std::string(\"0\")", help: `` },
      "p_seq": { key: "p_seq", label: "FASTA sequence for proteins:", type: "text", default: "LABEL_SEQUENCE_CPIPE", help: `` },
