      "subvolume_dimensions": { key: "subvolume_dimensions", label: "Sub-volume dimensions (px):", type: "number", default: 72, min: 64, max: 256, step: 1, help: `Dimensions (XYZ) in pixels of the sub-volumes to be extracted from the training tomograms. Corresponds to patch_size in cryoCARE_extract_train_data.py.` },
      "tomograms_for_training": { key: "tomograms_for_training", label: "Tomograms for model training:", type: "text", default: "std::string(\"\")", help: `` },
