  "tomo_extract": {
    tabs: [
      { label: "I/O", options: [
      ] },
      { label: "Reconstruct", options: [
        { key: "binning", expert: true, world: "both" },
        { key: "box_size", expert: true, world: "both" },
        { key: "crop_size", expert: true, world: "both" },
        { key: "do_stack2d", expert: true, world: "both" },
        { key: "do_float16", expert: true, world: "both" },
        { key: "do_real_subtomo", expert: true, world: "both" },
      ] },
    ],
    options: {
      "binning": { key: "binning", label: "Binning factor:", type: "number", default: 1, min: 1, max: 16, step: 1, flag: "--bin", help: `The tilt series images will be binned by this (real-valued) factor and then reconstructed in the specified box size above. Note that thereby the reconstructed region becomes larger when specifying binning factors larger than one.` },
      "box_size": { key: "box_size", label: "Box size (binned pix):", type: "number", default: 128, min: 32, max: 512, step: 16, flag: "--b", help: `The initial box size of the reconstruction. A sufficiently large box size allows more of the high-frequency signal to be captured that has been delocalised by the CTF.` },
      "crop_size": { key: "crop_size", label: "Cropped box size (binned pix):", type: "number", default: -1, min: -1, max: 512, step: 16, help: `If set to a positive value, after construction, the resulting pseudo subtomograms are cropped to this size. A smaller box size allows the (generally expensive) refinement using relion_refine to proceed more rapidly.` },
      "do_float16": { key: "do_float16", label: "Write output in float16?", type: "bool", default: true, flag: "--float16", help: `If set to Yes, this program will write output images in float16 MRC format. This will save a factor of two in disk space compared to the default of writing in float32. Note that RELION and CCPEM will read float16 images, but other programs may not (yet) do so.` },
      "do_real_subtomo": { key: "do_real_subtomo", label: "Extract and re-project real subtomograms?", type: "bool", default: false, flag: "--real_subtomo", help: `If set to Yes, this program will box out real subtomograms from the input tomogram and then re-project these into 2D stacks that resemble the 2D stacks from windowed tilt series images. The size of the images is determined by the crop size; the pixel size is that of the tomogram. This will result in a particles.star file that is suitable for low-resolution subtomogram averaging and a particles_for_class2d.star file that can be used for fast 2D classification in order to select good particles. You can re-launch the GUI without the --tomo argument to get access to the Class2D job type. If set to No, the program will write out normal windowed tilt-series images that are suitable for high-resolution subtomogram averaging.` },
      "do_stack2d": { key: "do_stack2d", label: "Write output as 2D stacks?", type: "bool", default: true, flag: "--stack2d", help: `If set to Yes, this program will write output subtomograms as 2D substacks. This is new as of relion-4.1, and the preferred way of generating subtomograms. If set to No, then relion-4.0 3D pseudo-subtomograms will be written out. Either can be used in subsequent refinements and classifications.` },
      "max_dose": { key: "max_dose", label: "Maximum dose (e/A^2):", type: "number", default: -1, min: -1, max: 200, step: 1, help: `Tilt series frames with a dose higher than this maximum dose (in electrons per squared Angstroms) will not be included in the 3D pseudo-subtomogram, or in the 2D stack. For the latter, this will disc I/O operations and increase speed.` },
      "min_frames": { key: "min_frames", label: "Minimum nr. frames:", type: "number", default: 1, min: 1, max: 40, step: 1, help: `Each selected pseudo-subtomogram need to be visible in at least this number of tilt series frames with doses below the maximum dose` },
    },
  },
